PINS = {'packages/jobs/scheduler.py': 'bcb06f73143ef7a0'}
EDITS = {'packages/jobs/scheduler.py': [('lines 628-629', '        # which input hashes matched instead of leaving it to archaeology.\n        try:\n', "        # which input hashes matched instead of leaving it to archaeology.\n        #\n        # THE WHOLE FINGERPRINT (0.254.0): ``fingerprint`` is every component the digest hashes. The receipt used to\n        # carry six of the twelve, and a job re-ran on the panel's trial level with all six identical. When the\n        # digest moves, the last receipt is kept as ``fingerprint.previous.json`` so `packages.jobs.receipts` can\n        # say which component moved.\n        try:\n"), ('lines 631-632', '            import json as _json\n            receipt_dir = self.jobs_dir / job.job_id\n', '            import json as _json\n            from packages.jobs import receipts as _receipts\n            receipt_dir = self.jobs_dir / job.job_id\n'), ('lines 634-634', '            (receipt_dir / "fingerprint.last.json").write_text(_json.dumps({\n', '            last = receipt_dir / _receipts.LAST\n            before = _receipts.read(last)\n            if before is not None and before.get("digest") != job.build_fingerprint:\n                last.replace(receipt_dir / _receipts.PREVIOUS)\n            last.write_text(_json.dumps({\n'), ('lines 643-644', '                "inputs": raw_inputs,\n                "evaluated_utc": _dt.datetime.now(\n', '                "inputs": raw_inputs,\n                "fingerprint": fp.as_dict(),\n                "evaluated_utc": _dt.datetime.now(\n')]}
NEW_FILES = {'packages/jobs/receipts.py': '"""Why a job ran again: its fingerprint receipts, read back.\n\nTHE RECEIPT IS THE WHOLE DECISION. The scheduler writes ``fingerprint.last.json`` beside every job it evaluates,\ncache hit or not, and since 0.254.0 its ``fingerprint`` holds every component the cache digest hashes\n(`BuildFingerprint.as_dict`). Before, it recorded the adapter\'s inputs and versions but not the executable\nversions, the normalised arguments, the declared environment, the upstream hashes, the seed or the output contract\n-- six of the digest\'s twelve components -- so a job could re-run with every recorded input identical and nothing on\ndisk saying why. The Level Factory panel\'s trial level did exactly that (the factory\'s\n`docs/findings/rerun_receipts/`).\n\nTHE PREVIOUS RECEIPT IS KEPT as ``fingerprint.previous.json`` whenever the digest moves, so `differences` can name\nwhat changed between the evaluation that built the cached output and the one that rebuilt it.\n"""\nfrom __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nLAST = "fingerprint.last.json"\nPREVIOUS = "fingerprint.previous.json"\n\n\ndef read(path: Path) -> dict | None:\n    try:\n        data = json.loads(Path(path).read_text(encoding="utf-8"))\n    except (OSError, ValueError):\n        return None\n    return data if isinstance(data, dict) else None\n\n\ndef _flat(value, prefix: str, out: dict) -> dict:\n    if isinstance(value, dict):\n        for k, v in value.items():\n            _flat(v, "%s/%s" % (prefix, k), out)\n    else:\n        out[prefix or "/"] = value\n    return out\n\n\ndef differences(job_dir: Path) -> list[str] | None:\n    """What moved in the digest between the previous receipt and the last: ``["/executable_versions/python: 3.14.0\n    -> 3.13.9", ...]``, empty when they agree. ``None`` when either receipt is missing, unreadable, or written before\n    receipts carried the whole fingerprint (0.254.0): then the question cannot be answered from disk."""\n    prev, last = read(Path(job_dir) / PREVIOUS), read(Path(job_dir) / LAST)\n    if not prev or not last or "fingerprint" not in prev or "fingerprint" not in last:\n        return None\n    a, b = _flat(prev["fingerprint"], "", {}), _flat(last["fingerprint"], "", {})\n    return ["%s: %s -> %s" % (k, a.get(k, "(absent)"), b.get(k, "(absent)"))\n            for k in sorted(set(a) | set(b)) if k != "/digest" and a.get(k) != b.get(k)]\n', 'tests/unit/test_receipt_names_every_digest_input.py': '"""A job\'s fingerprint receipt records everything its cache digest hashes, and why it ran again (0.254.0).\n\nThe receipt (`fingerprint.last.json`) claimed to record WHAT the cache decision was based on, but carried six of the\ndigest\'s twelve components. On the factory\'s panel trial level a job re-ran with every recorded input byte-identical\nand its site spec unchanged: the digest had moved on something the receipt did not say. These tests hold the\nreceipt to the digest -- recomputing it from the receipt alone must give the recorded digest -- and keep the\nprevious receipt when the digest moves, so the difference is on disk. FAILS ON 0.253.0.\n"""\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\n\nfrom packages.adapters.registry import AdapterRegistry  # noqa: E402\nfrom packages.adapters.sdk import BaseAdapter, PlannedCommand, ToolProbe  # noqa: E402\nfrom packages.artifacts.cache import ContentCache  # noqa: E402\nfrom packages.artifacts.provenance import BuildFingerprint  # noqa: E402\nfrom packages.core.models import Job  # noqa: E402\nfrom packages.jobs import receipts  # noqa: E402\nfrom packages.jobs.scheduler import Scheduler  # noqa: E402\nfrom packages.pipeline.graph import JobGraph  # noqa: E402\nfrom packages.project_store.index import Index  # noqa: E402\n\n\nclass _Adapter(BaseAdapter):\n    adapter_id = "fake_receipt"\n    adapter_version = "0.1.0"\n    capabilities = frozenset({"x"})\n    output_contract_version = "fake.0.1"\n    tally: Path | None = None\n    python = "3.14.0"                   # what the probe reports: the knob a re-run turns\n\n    def probe(self, installation):\n        return ToolProbe(True, "0.1.0", None, {"python": self.python}, self.capabilities)\n\n    def validate_configuration(self, job_spec, context):\n        return []\n\n    def fingerprint_inputs(self, job_spec, context):\n        return {"spec": "unchanged"}\n\n    def plan_commands(self, job_spec, context):\n        work = Path(str(context["work_dir"]))\n        script = (f"open({str(work / \'out.json\')!r}, \'w\').write(\'{{}}\'); "\n                  f"open({str(self.tally)!r}, \'a\').write(\'x\')")\n        return [PlannedCommand(executable=Path(sys.executable), arguments=("-c", script), working_directory=work,\n                               expected_outputs=("out.json",), resource_class="lightweight", timeout_seconds=30)]\n\n    def normalize_validation(self, output_paths):\n        return []\n\n\ndef _run(tmp_path, python):\n    adapter = _Adapter()\n    adapter.tally, adapter.python = tmp_path / "ran.log", python\n    index = Index(tmp_path / "index.sqlite")\n    sched = Scheduler(index=index, cache=ContentCache(tmp_path / "cache"),\n                      registry=AdapterRegistry({"fake_receipt": adapter}), jobs_dir=tmp_path / "jobs",\n                      installation={"repositories": {"fake_receipt": str(tmp_path)},\n                                    "python_executable": sys.executable})\n    graph = JobGraph()\n    graph.add(Job(job_id="m.fake", mission_id="m", stage_id="s", adapter_id="fake_receipt"))\n    try:\n        sched.run(graph, job_specs={"m.fake": {"seed": 1}}, mission_id="m")\n    finally:\n        index.close()\n    return tmp_path / "jobs" / "m.fake"\n\n\ndef _recomputed(receipt):\n    fields = {k: v for k, v in receipt["fingerprint"].items() if k != "digest"}\n    return BuildFingerprint(**fields).digest()\n\n\ndef test_the_digest_can_be_recomputed_from_the_receipt_alone(tmp_path):\n    job = _run(tmp_path, "3.14.0")\n    r = receipts.read(job / receipts.LAST)\n    assert r["fingerprint"]["executable_versions"] == {"python": "3.14.0"}\n    assert _recomputed(r) == r["digest"] == r["fingerprint"]["digest"]\n\n\ndef test_a_cache_hit_keeps_one_receipt_and_says_nothing_moved(tmp_path):\n    job = _run(tmp_path, "3.14.0")\n    _run(tmp_path, "3.14.0")\n    assert (tmp_path / "ran.log").read_text() == "x"                  # one run, one hit\n    assert not (job / receipts.PREVIOUS).exists() and receipts.differences(job) is None\n\n\ndef test_a_re_run_keeps_the_previous_receipt_and_names_what_moved(tmp_path):\n    job = _run(tmp_path, "3.14.0")\n    _run(tmp_path, "3.13.9")                                           # every input the same; the interpreter not\n    assert (tmp_path / "ran.log").read_text() == "xx"\n    prev, last = receipts.read(job / receipts.PREVIOUS), receipts.read(job / receipts.LAST)\n    assert prev["inputs"] == last["inputs"] and prev["digest"] != last["digest"]\n    assert receipts.differences(job) == ["/executable_versions/python: 3.14.0 -> 3.13.9"]\n    assert _recomputed(prev) == prev["digest"] and _recomputed(last) == last["digest"]\n\n\ndef test_receipts_written_before_they_were_whole_cannot_answer(tmp_path):\n    (tmp_path / receipts.PREVIOUS).write_text(\'{"digest": "a", "inputs": {}}\', encoding="utf-8")\n    (tmp_path / receipts.LAST).write_text(\'{"digest": "b", "inputs": {}}\', encoding="utf-8")\n    assert receipts.differences(tmp_path) is None\n'}
CHANGELOG = "## [0.254.0] - a job's receipt records everything its cache digest hashes\n\n### Fixed\n- **`fingerprint.last.json` now records the whole fingerprint.** The scheduler's receipt says it records what a cache\n  decision was based on, but it carried the adapter version, tool version, repository commit and inputs. The digest\n  also hashes the executable versions, normalised arguments, declared environment, upstream artifact hashes, seed\n  and output contract.\n  - A job could re-run with every recorded input byte-identical and nothing on disk saying why. The factory's panel\n    trial level did, three times (the factory's `docs/findings/rerun_receipts/`).\n  - The receipt now carries `fingerprint`: `BuildFingerprint.as_dict()`, every component and the digest.\n\n### Added\n- **`fingerprint.previous.json`**: when a job's digest moves, its last receipt is kept beside the new one.\n- **`packages/jobs/receipts.py`**: `differences(job_dir)` names each component that moved between the two. It returns\n  `None` when either receipt predates this release, because those cannot answer.\n\n### Tests\n- `tests/unit/test_receipt_names_every_digest_input.py`, driving the real scheduler with a fake adapter:\n  - the digest is recomputed from the receipt alone and matches;\n  - a cache hit keeps one receipt;\n  - a re-run caused only by an interpreter change keeps the previous receipt and names `executable_versions` as what\n    moved;\n  - receipts written before this release cannot answer.\n  - Fails on 0.253.0. With only the scheduler change withheld, the two tests that need it fail.\n\n"
OLD_VERSION, NEW_VERSION = '0.253.0', '0.254.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
